  it("checkpoints flow state before waiting for ask input", async () => {
    const saves: Array<{ flowId: string; methodName: string; state: Record<string, unknown> }> = [];
    const persistence = {
      saveState: (flowId: string, methodName: string, state: unknown) => {
        saves.push({ flowId, methodName, state: { ...(state as Record<string, unknown>) } });
      },
    };

    class CheckpointAskFlow extends Flow<{ id: string; topic?: string; providerSawCheckpoint?: boolean }> {
      gather() {
        this.state.topic = "CrewAI";
        return this.ask("Topic?");
      }
    }

    const flow = new CheckpointAskFlow({
      initialState: { id: "ask-flow", topic: undefined, providerSawCheckpoint: false },
      persistence: persistence as unknown as JsonFlowPersistence,
      inputProvider: {
        requestInput: (_message, providerFlow) => {
          providerFlow.state.providerSawCheckpoint = saves.some((save) =>
            save.flowId === "ask-flow"
            && save.methodName === "_ask_checkpoint"
            && save.state.topic === "CrewAI",
          );
          return "confirmed";
        },
      },
    });
    decorateMethod(CheckpointAskFlow, "gather", start() as unknown as Decorator).call(flow);

    await expect(flow.kickoff()).resolves.toBe("confirmed");
    expect(flow.state.providerSawCheckpoint).toBe(true);
    expect(saves.filter((save) => save.methodName === "_ask_checkpoint")).toEqual([{
      flowId: "ask-flow",
      methodName: "_ask_checkpoint",
      state: { id: "ask-flow", topic: "CrewAI", providerSawCheckpoint: false },
    }]);
    expect(saves.at(-1)).toMatchObject({
      flowId: "ask-flow",
      methodName: "gather",
      state: { id: "ask-flow", topic: "CrewAI", providerSawCheckpoint: true },
    });
  });

  it("checkpoints state before each ask so later asks can recover earlier answers", async () => {
    const saves: Array<{ methodName: string; state: Record<string, unknown> }> = [];
    const answers = ["AI", "detailed"];
    const persistence = {
      saveState: (_flowId: string, methodName: string, state: unknown) => {
        saves.push({ methodName, state: { ...(state as Record<string, unknown>) } });
      },
    };

    class RecoverableAskFlow extends Flow<{ id: string; topic?: string; depth?: string }> {
      gather() {
        if (!this.state.topic) {
          this.state.topic = this.ask("Topic?") as string;
        }
        if (!this.state.depth) {
          this.state.depth = this.ask("Depth?") as string;
        }
        return { topic: this.state.topic, depth: this.state.depth };
      }
    }

    const flow = new RecoverableAskFlow({
      initialState: { id: "recoverable-ask" },
      persistence: persistence as unknown as JsonFlowPersistence,
      inputProvider: {
        requestInput: () => answers.shift() ?? null,
      },
    });
    decorateMethod(RecoverableAskFlow, "gather", start() as unknown as Decorator).call(flow);

    await expect(flow.kickoff()).resolves.toEqual({ topic: "AI", depth: "detailed" });

    const askCheckpoints = saves.filter((save) => save.methodName === "_ask_checkpoint");
    expect(askCheckpoints).toHaveLength(2);
    expect(askCheckpoints[0]?.state).toEqual({ id: "recoverable-ask" });
    expect(askCheckpoints[1]?.state).toEqual({ id: "recoverable-ask", topic: "AI" });
    expect(flow.inputHistory.map((entry) => [entry.message, entry.response])).toEqual([
      ["Topic?", "AI"],
      ["Depth?", "detailed"],
    ]);
  });

