  it("loads persisted state from kickoff inputs id before applying default overrides", async () => {
    const directory = mkdtempSync(join(tmpdir(), "crewai-ts-flow-default-override-"));
    const persistence = new JsonFlowPersistence(directory);

    class DefaultOverrideFlow extends Flow<{ id: string; sentenceCount: number; hasSetCount: boolean }> {
      constructor() {
        super({
          initialState: {
            id: "poem-flow",
            sentenceCount: 1000,
            hasSetCount: false,
          },
          persistence,
        });
      }

      setSentenceCount() {
        if (this.state.hasSetCount && this.state.sentenceCount === 2) {
          this.state.sentenceCount = 3;
        } else if (this.state.hasSetCount && this.state.sentenceCount === 1000) {
          this.state.sentenceCount = 1000;
        } else if (this.state.hasSetCount && this.state.sentenceCount === 5) {
          this.state.sentenceCount = 5;
        } else {
          this.state.sentenceCount = 2;
          this.state.hasSetCount = true;
        }
      }
    }

    const initializer = decorateMethod(DefaultOverrideFlow, "setSentenceCount", start() as unknown as Decorator);
    const first = new DefaultOverrideFlow();
    initializer.call(first);
    await first.kickoff();

    expect(first.state.sentenceCount).toBe(2);
    await expect(persistence.loadState("poem-flow")).resolves.toMatchObject({
      sentenceCount: 2,
      hasSetCount: true,
    });

    const second = new DefaultOverrideFlow();
    initializer.call(second);
    await second.kickoff({ inputs: { id: "poem-flow" } });

    expect(second.state.sentenceCount).toBe(3);

    const third = new DefaultOverrideFlow();
    initializer.call(third);
    await third.kickoff({
      inputs: {
        id: "poem-flow",
        hasSetCount: true,
        sentenceCount: 5,
      },
    });

    expect(third.state.sentenceCount).toBe(5);

    const fourth = new DefaultOverrideFlow();
    initializer.call(fourth);
    await fourth.kickoff({ inputs: { id: "fresh-poem-flow", hasSetCount: true } });

    expect(fourth.state.sentenceCount).toBe(1000);
  });

  it("carries persisted default overrides through multi-step flow listeners", async () => {
    const directory = mkdtempSync(join(tmpdir(), "crewai-ts-flow-multistep-default-"));
    const persistence = new JsonFlowPersistence(directory);

    class MultiStepDefaultOverrideFlow extends Flow<{
      id: string;
      sentenceCount: number;
      hasSetCount: boolean;
      poemType: string;
    }> {
      constructor() {
        super({
          initialState: {
            id: "multi-poem-flow",
            sentenceCount: 1000,
            hasSetCount: false,
            poemType: "",
          },
          persistence,
        });
      }

      setSentenceCount() {
        if (!this.state.hasSetCount) {
          this.state.sentenceCount = 3;
          this.state.hasSetCount = true;
        }
      }

      setPoemType() {
        if (this.state.sentenceCount === 3) {
          this.state.poemType = "haiku";
        } else if (this.state.sentenceCount === 5) {
          this.state.poemType = "limerick";
        } else {
          this.state.poemType = "free_verse";
        }
      }

      finished() {
        return this.state.poemType;
      }
    }

    const setCountInitializer = decorateMethod(MultiStepDefaultOverrideFlow, "setSentenceCount", start() as unknown as Decorator);
    const setTypeInitializer = decorateMethod(MultiStepDefaultOverrideFlow, "setPoemType", listen("setSentenceCount") as unknown as Decorator);
    const finishedInitializer = decorateMethod(MultiStepDefaultOverrideFlow, "finished", listen("setPoemType") as unknown as Decorator);
    const initialize = (flow: MultiStepDefaultOverrideFlow) => {
      setCountInitializer.call(flow);
      setTypeInitializer.call(flow);
      finishedInitializer.call(flow);
    };

    const first = new MultiStepDefaultOverrideFlow();
    initialize(first);
    await first.kickoff();

    expect(first.state.sentenceCount).toBe(3);
    expect(first.state.poemType).toBe("haiku");

    const second = new MultiStepDefaultOverrideFlow();
    initialize(second);
    await second.kickoff({
      inputs: {
        id: "multi-poem-flow",
        sentenceCount: 5,
      },
    });

    expect(second.state.sentenceCount).toBe(5);
    expect(second.state.poemType).toBe("limerick");

    const third = new MultiStepDefaultOverrideFlow();
    initialize(third);
    await third.kickoff({ inputs: { id: "multi-poem-flow" } });

    expect(third.state.sentenceCount).toBe(5);
    expect(third.state.poemType).toBe("limerick");
  });

  it("resumes persisted flows without re-executing completed listener methods", async () => {
    const directory = mkdtempSync(join(tmpdir(), "crewai-ts-flow-resume-listeners-"));
    const persistence = new JsonFlowPersistence(directory);
    const executionLog: string[] = [];

    class ListenerResumeFlow extends Flow<{ id: string; step1?: string; step2?: string; step3?: string }> {
      constructor() {
        super({ initialState: { id: "listener-flow" }, persistence });
      }

      step1() {
        executionLog.push("step1");
        this.state.step1 = "done";
        return "step1_result";
      }

      step2() {
        executionLog.push("step2");
        this.state.step2 = "done";
        return "step2_result";
      }

      step3() {
        executionLog.push("step3");
        this.state.step3 = "done";
        return "step3_result";
      }
    }

    const initializers = [
      decorateMethod(ListenerResumeFlow, "step1", start() as unknown as Decorator),
      decorateMethod(ListenerResumeFlow, "step2", listen("step1") as unknown as Decorator),
      decorateMethod(ListenerResumeFlow, "step3", listen("step2") as unknown as Decorator),
    ];
    const first = new ListenerResumeFlow();
    initializers.forEach((initializer) => {
      initializer.call(first);
    });
    await first.kickoff();

    expect(executionLog).toEqual(["step1", "step2", "step3"]);

    const second = new ListenerResumeFlow();
    initializers.forEach((initializer) => {
      initializer.call(second);
    });
    (second as unknown as {
      runtimeCompletedMethods: Set<string>;
      runtimeMethodOutputs: unknown[];
    }).runtimeCompletedMethods = new Set(["step1", "step2"]);
    (second as unknown as {
      runtimeCompletedMethods: Set<string>;
      runtimeMethodOutputs: unknown[];
    }).runtimeMethodOutputs = ["step1_result", "step2_result"];
    executionLog.length = 0;

    await second.kickoff({ inputs: { id: "listener-flow" } });

    expect(executionLog).toEqual(["step3"]);
    expect(second.state).toMatchObject({
      id: "listener-flow",
      step1: "done",
      step2: "done",
      step3: "done",
    });
  });

