  it("mirrors upstream original tool usage state when converted to structured tool", () => {
    const noCache = () => false;
    class EchoTool extends BaseTool {
      constructor() {
        super({
          name: "echo tool",
          description: "Echo a value",
          argsSchema: {
            value: { type: "string", required: true },
          },
          maxUsageCount: 2,
          cacheFunction: noCache,
        });
      }

      protected _run(args: Record<string, unknown>): string {
        return String(args.value);
      }
    }

    const original = new EchoTool();
    const structured = original.to_structured_tool();

    expect(original.cache_function).toBe(noCache);
    expect(structured.cache_function).toBe(noCache);
    expect(structured.current_usage_count).toBe(0);
    expect(original.current_usage_count).toBe(0);
    expect(structured.invoke({ value: "first" })).toBe("first");
    expect(structured.current_usage_count).toBe(1);
    expect(original.current_usage_count).toBe(1);
    expect(structured.invoke({ value: "second" })).toBe("second");
    expect(original.has_reached_max_usage_count()).toBe(true);
    expect(() => structured.invoke({ value: "third" })).toThrow("Tool 'echo_tool' has reached its maximum usage limit of 2. You should not use the echo_tool tool again.");
    expect(original.current_usage_count).toBe(2);

    const alreadyStructured = new StructuredTool({
      name: "already structured",
      description: "Already structured",
      func: () => "ok",
    });
    const converted = to_langchain([original, alreadyStructured]);
    expect(converted).toHaveLength(2);
    expect(converted[0]).toBeInstanceOf(StructuredTool);
    expect(converted[1]).toBe(alreadyStructured);
    expect(to_langchain(original)).toBeInstanceOf(StructuredTool);
  });

  it("uses upstream BaseTool async execution semantics", async () => {
    class SyncOnlyTool extends BaseTool {
      constructor() {
        super({
          name: "sync only",
          description: "Sync only",
          argsSchema: {
            value: { type: "string", required: true },
          },
        });
      }

      protected _run(args: Record<string, unknown>): string {
        return String(args.value);
      }
    }
    class AsyncEchoTool extends BaseTool {
      constructor() {
        super({
          name: "async echo",
          description: "Async echo",
          argsSchema: {
            value: { type: "string", required: true },
          },
        });
      }

      protected _run(args: Record<string, unknown>): string {
        return String(args.value);
      }

      protected override async _arun(args: Record<string, unknown>): Promise<string> {
        return await Promise.resolve(`async:${String(args.value)}`);
      }
    }

    const syncOnly = new SyncOnlyTool();
    await expect(syncOnly.arun({ value: "CrewAI" })).rejects.toThrow("does not implement _arun");
    expect(syncOnly.current_usage_count).toBe(1);

    const asyncEcho = new AsyncEchoTool();
    await expect(asyncEcho.arun({ value: "CrewAI" })).resolves.toBe("async:CrewAI");
    expect(asyncEcho.current_usage_count).toBe(1);
  });

