  it("handles upstream-style BaseLLM completion and response helpers", async () => {
    const llm = new ConfiguredLLM({
      model: "gpt-4o",
      temperature: 0.2,
      stop: ["STOP"],
      additional_params: { stream: true, top_p: 0.8 },
    });
    const params = llm._prepare_completion_params("hello", [{ type: "function", function: { name: "search_docs" } }]);

    expect(params).toMatchObject({
      model: "gpt-4o",
      temperature: 0.2,
      stream: true,
      top_p: 0.8,
      messages: [{ role: "user", content: "hello" }],
      stop: ["STOP"],
      tools: [{ type: "function", function: { name: "search_docs" } }],
    });

    await expect(llm._handle_tool_call([{
      function: { name: "search_docs", arguments: "{\"query\":\"CrewAI\"}" },
    }], {
      search_docs: ({ query }) => `found ${String(query)}`,
    })).resolves.toBe("found CrewAI");

    const chunks = [
      { id: "response-1", choices: [{ delta: { content: "hel" } }] },
      { choices: [{ delta: { content: "lo" } }], usage: { prompt_tokens: 4, completion_tokens: 2 } },
    ];
    const seenChunks: unknown[] = [];
    const usageEvents: unknown[] = [];
    const usageCallback = {
      log_success_event: (_kwargs: Record<string, unknown>, responseObj: Record<string, unknown>) => {
        usageEvents.push(responseObj);
      },
    };

    await expect(llm._handle_streaming_response(
      { chunks, messages: params.messages },
      [(chunk: unknown) => seenChunks.push(chunk), usageCallback],
    )).resolves.toBe("hello");
    expect(seenChunks).toHaveLength(2);
    expect(usageEvents).toEqual([{ usage: { prompt_tokens: 4, completion_tokens: 2 } }]);

    expect(llm._handle_non_streaming_response({
      response: { choices: [{ message: { content: "done" } }], usage: { total_tokens: 3 } },
      messages: params.messages,
    })).toBe("done");
    await expect(llm._ahandle_non_streaming_response({
      response: { choices: [{ message: { content: "async done" } }] },
      messages: params.messages,
    })).resolves.toBe("async done");
    await expect(llm._ahandle_streaming_response({ chunks })).resolves.toBe("hello");

    const accumulated: Record<number, AccumulatedToolArgs> = {};
    await expect(llm._handle_streaming_tool_calls([
      { index: 0, function: { name: "search_docs", arguments: "{\"query\":" } },
      { index: 0, function: { arguments: "\"CrewAI\"}" } },
    ], accumulated, {
      search_docs: ({ query }) => `streamed ${String(query)}`,
    })).resolves.toBe("streamed CrewAI");
  });

  it("emits upstream-style streaming tool-call chunk events", async () => {
    const llm = new ConfiguredLLM({ model: "gpt-4o" });
    const events: LLMStreamChunkEvent[] = [];
    const listener = (_source: unknown, event: LLMStreamChunkEvent) => {
      events.push(event);
    };
    crewaiEventBus.on("llm_stream_chunk", listener);
    try {
      const accumulated: Record<number, AccumulatedToolArgs> = {};
      await expect(llm._handle_streaming_tool_calls([
        { index: 0, id: "call-1", type: "function", function: { name: "search_docs", arguments: "{\"query\":" } },
        { index: 0, function: { arguments: "\"CrewAI\"}" } },
      ], accumulated, null, { id: "task-1" }, { role: "agent" }, "response-1")).resolves.toBeNull();
    } finally {
      crewaiEventBus.off("llm_stream_chunk", listener);
    }

    expect(events).toHaveLength(2);
    expect(events.map((event) => event.call_type)).toEqual([LLMCallType.TOOL_CALL, LLMCallType.TOOL_CALL]);
    expect(events.map((event) => event.response_id)).toEqual(["response-1", "response-1"]);
    expect(events.map((event) => event.chunk)).toEqual(["{\"query\":", "\"CrewAI\"}"]);
    expect(events[0].tool_call).toMatchObject({
      id: "call-1",
      type: "function",
      function: { name: "search_docs", arguments: "{\"query\":" },
    });
    expect(events[1].tool_call).toMatchObject({
      id: "call-1",
      type: "function",
      function: { name: "search_docs", arguments: "{\"query\":\"CrewAI\"}" },
    });
  });

  it("calls object providers with tools and aggregates usage metrics", async () => {
    const calls: Array<{ messages: readonly LLMMessage[]; options: LLMCallOptions | undefined }> = [];
    const events: CrewAIEvent[] = [];
    crewaiEventBus.on("agent_execution_started", (_source, event) => {
      events.push(event);
    });
    crewaiEventBus.on("llm_call_started", (_source, event) => {
      events.push(event);
    });
    crewaiEventBus.on("llm_call_completed", (_source, event) => {
      events.push(event);
    });
    crewaiEventBus.on("agent_execution_completed", (_source, event) => {
      events.push(event);
    });
    let usage: UsageMetrics = {
      totalTokens: 0,
      promptTokens: 0,
      cachedPromptTokens: 0,
      completionTokens: 0,
      reasoningTokens: 0,
      cacheCreationTokens: 0,
      successfulRequests: 0,
    };
    const llm = {
      call(messages: readonly LLMMessage[], options?: LLMCallOptions) {
        calls.push({ messages, options });
        usage = {
          ...usage,
          totalTokens: usage.totalTokens + 12,
          promptTokens: usage.promptTokens + 8,
          completionTokens: usage.completionTokens + 4,
          successfulRequests: usage.successfulRequests + 1,
        };
        return "provider output";
      },
      getUsageMetrics() {
        return usage;
      },
    };
    const toolInstance = new StructuredTool({
      name: "search",
      description: "Search",
      func: () => "unused",
    });
    const agentInstance = new Agent({
      role: "Researcher",
      goal: "Find facts",
      backstory: "Careful analyst",
      tools: [toolInstance],
      llm,
    });
    const taskInstance = new Task({
      description: "Research",
      expectedOutput: "A concise brief",
      agent: agentInstance,
    });

    const output = await new Crew({ agents: [agentInstance], tasks: [taskInstance] }).kickoff();

    expect(output.raw).toBe("provider output");
    expect(calls[0]?.options?.tools).toEqual([toolInstance]);
    expect(agentInstance.getUsageMetrics()).toMatchObject({
      totalTokens: 12,
      promptTokens: 8,
      completionTokens: 4,
      successfulRequests: 1,
    });
    expect(output.tokenUsage).toMatchObject({
      totalTokens: 12,
      promptTokens: 8,
      completionTokens: 4,
      successfulRequests: 1,
    });
    expect(events.map((event) => event.type)).toEqual([
      "agent_execution_started",
      "llm_call_started",
      "llm_call_completed",
      "agent_execution_completed",
    ]);
    expect(events[0]).toBeInstanceOf(AgentExecutionStartedEvent);
    expect((events[0] as AgentExecutionStartedEvent).task).toBe(taskInstance);
    expect(events[1]).toBeInstanceOf(LLMCallStartedEvent);
    expect((events[1] as LLMCallStartedEvent).from_agent).toBe(agentInstance);
    expect((events[1] as LLMCallStartedEvent).from_task).toBe(taskInstance);
    expect(events[2]).toBeInstanceOf(LLMCallCompletedEvent);
    expect((events[2] as LLMCallCompletedEvent).call_type).toBe(LLMCallType.LLM_CALL);
    expect((events[2] as LLMCallCompletedEvent).usage).toMatchObject({
      totalTokens: 12,
      successfulRequests: 1,
    });
    expect(events[3]).toBeInstanceOf(AgentExecutionCompletedEvent);
    expect((events[3] as AgentExecutionCompletedEvent).output).toBe("provider output");
  });

