    writeFileSync(jsonPath, JSON.stringify({ nest: { mode: "library consumption" } }), "utf8");
    writeFileSync(csvPath, "topic,detail\nDecorators,\"standard, no reflect metadata\"\n", "utf8");

    const prompts: string[] = [];
